cd /workspace && python3 -c "
# Test POST with None title (wrong type)
data = {'title': None, 'author': 'Alice', 'isbn': '123'}
title = data.get('title')
author = data.get('author')
isbn = data.get('isbn')
try:
    if not title.strip() or not author.strip() or not isbn.strip():
        print('entered validation block')
except Exception as e:
    print('Exception:', type(e).__name__, e)

print()

# Test POST with list title
data = {'title': [1,2,3], 'author': 'Alice', 'isbn': '123'}
title = data.get('title')
author = data.get('author')
isbn = data.get('isbn')
try:
    if not title.strip() or not author.strip() or not isbn.strip():
        print('entered validation block')
except Exception as e:
    print('Exception:', type(e).__name__, e)

print()

# Test POST with title that is empty string
data = {'title': '', 'author': 'Alice', 'isbn': '123'}
title = data.get('title')
author = data.get('author')
isbn = data.get('isbn')
try:
    if not title.strip() or not author.strip() or not isbn.strip():
        print('entered validation block - would be 400 (empty)')
except Exception as e:
    print('Exception:', type(e).__name__, e)

print()

# Test POST with title that is whitespace
data = {'title': '   ', 'author': 'Alice', 'isbn': '123'}
title = data.get('title')
author = data.get('author')
isbn = data.get('isbn')
try:
    if not title.strip() or not author.strip() or not isbn.strip():
        print('entered validation block - would be 400 (whitespace)')
except Exception as e:
    print('Exception:', type(e).__name__, e)

print()

# Test POST with title as integer but non-empty
data = {'title': 123, 'author': 'Alice', 'isbn': '123'}
title = data.get('title')
author = data.get('author')
isbn = data.get('isbn')
# This is the critical case - wrong type should be 400
try:
    if not title.strip() or not author.strip() or not isbn.strip():
        print('Entered validation block (should NOT happen for int)')
except AttributeError as e:
    print('AttributeError caught - but this leads to 500, should be 400! Exception:', e)
except Exception as e:
    print('Exception:', type(e).__name__, e)
"
